WITH base AS (SELECT id, brand, cost, launch_date, tags, supplier_id, ROUND(price / cost, 2) margin, ADD_MONTHS(launch_date, 6) launch_date_plus_months FROM products WHERE supplier_id IS NOT NULL AND product_name LIKE '%Cance%') SELECT CASE WHEN cost >= 690 THEN 'HIGH' ELSE 'LOW' END AS cost_tier, COUNT(*) AS event_count, ROUND(AVG(margin), 2) AS avg_margin, MAX(margin) FILTER (WHERE brand = 'Stark') AS stark_max_margin, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN brand = 'Acme' THEN 1 END), 0), 2) AS cost_per_acme, SUM(CASE WHEN brand = 'Stark' THEN cost ELSE 0 END) AS stark_cost, GROUPING_ID() AS grouping_level FROM base GROUP BY ROLLUP (CASE WHEN cost >= 690 THEN 'HIGH' ELSE 'LOW' END) HAVING event_count > 1 ORDER BY cost_per_acme DESC NULLS FIRST
